try {
    var data   = msg.payload;
    var slots  = {};
    var now    = Date.now();
    var cutoff = now + 48 * 3600 * 1000;

    // uur_verw: hourly forecast array, 24 slots
    // timestamp is UTC Unix seconds — use it directly for the key
    // gr is already in W/m² (global radiation) — feeds solar consensus
    if (data && data.uur_verw) {
        data.uur_verw.forEach(function(item) {
            var slotMs = item.timestamp * 1000;
            if (slotMs < now - 3600000 || slotMs > cutoff) return;
            var d = new Date(slotMs);
            d.setMinutes(0, 0, 0);
            var key = d.toISOString();
            slots[key] = {
                temp_c:               item.temp,
                wind_kph:             item.windkmh,
                wind_dir_deg:         item.windrgr,
                precip_mm:            item.neersl  || 0,
                rain_prob:            null,
                cloud_pct:            null,
                solar_radiation_wm2:  (item.gr !== undefined && item.gr !== null) ? item.gr : null,
                direct_radiation_wm2: null,
                diffuse_radiation_wm2:null,
                uv_index:             null
            };
        });
    }
    msg.payload = { source: 'weerlive', slots: slots };
} catch(e) {
    node.warn('Weerlive parse error: ' + e.message);
    msg.payload = { source: 'weerlive', slots: {} };
}
