try {
    var data = msg.payload;
    var slots = {};
    var now    = Date.now();
    var cutoff = now + 48 * 3600 * 1000;

    if (data && data.list) {
        data.list.forEach(function(item) {
            var baseTime = item.dt * 1000;
            if (baseTime > cutoff + 3 * 3600 * 1000) return;
            // OWM gives 3h blocks — copy values to each of the 3 hourly slots
            for (var h = 0; h < 3; h++) {
                var slotMs = baseTime + h * 3600 * 1000;
                if (slotMs < now - 3600000 || slotMs > cutoff) continue;
                var d = new Date(slotMs);
                d.setMinutes(0, 0, 0);
                var key = d.toISOString();
                var precip3h = (item.rain && item.rain['3h']) ? item.rain['3h'] : 0;
                var snow3h   = (item.snow && item.snow['3h']) ? item.snow['3h'] : 0;
                slots[key] = {
                    temp_c:       item.main.temp,
                    wind_kph:     (item.wind.speed || 0) * 3.6,
                    wind_dir_deg: item.wind.deg || 0,
                    precip_mm:    (precip3h + snow3h) / 3,
                    rain_prob:    item.pop || 0,
                    cloud_pct:    item.clouds ? item.clouds.all : null
                };
            }
        });
    }
    msg.payload = { source: 'owm', slots: slots };
} catch(e) {
    node.warn('OWM parse error: ' + e.message);
    msg.payload = { source: 'owm', slots: {} };
}
