try {
    var data = msg.payload;
    var slots = {};
    var now    = Date.now();
    var cutoff = now + 48 * 3600 * 1000;

    if (data && data.hourly && data.hourly.time) {
        var h = data.hourly;
        h.time.forEach(function(t, i) {
            // Times arrive as 'YYYY-MM-DDTHH:mm' (no Z) — treat as UTC
            var isoKey = (t.length === 16) ? t + ':00Z' : t;
            var slotMs = new Date(isoKey).getTime();
            if (isNaN(slotMs) || slotMs < now - 3600000 || slotMs > cutoff) return;
            var d = new Date(slotMs);
            d.setMinutes(0, 0, 0);
            var key = d.toISOString();
            slots[key] = {
                temp_c:       h.temperature_2m          ? h.temperature_2m[i]                      : null,
                wind_kph:     h.windspeed_10m           ? h.windspeed_10m[i]                       : null,
                wind_dir_deg: h.winddirection_10m       ? h.winddirection_10m[i]                   : null,
                precip_mm:    h.precipitation           ? (h.precipitation[i] || 0)                : 0,
                rain_prob:             h.precipitation_probability  ? (h.precipitation_probability[i]  || 0) / 100 : null,
                cloud_pct:             h.cloudcover                 ? h.cloudcover[i]                             : null,
                solar_radiation_wm2:   h.shortwave_radiation        ? Math.round(h.shortwave_radiation[i]  || 0)   : null,
                direct_radiation_wm2:  h.direct_radiation           ? Math.round(h.direct_radiation[i]    || 0)   : null,
                diffuse_radiation_wm2: h.diffuse_radiation          ? Math.round(h.diffuse_radiation[i]   || 0)   : null,
                uv_index:              h.uv_index                   ? Math.round((h.uv_index[i]           || 0) * 10) / 10 : null
            };
        });
    }
    msg.payload = { source: 'open_meteo', slots: slots };
} catch(e) {
    node.warn('Open-Meteo parse error: ' + e.message);
    msg.payload = { source: 'open_meteo', slots: {} };
}
