try {
    var data = msg.payload;
    var slots = {};
    var now    = Date.now();
    var cutoff = now + 48 * 3600 * 1000;

    if (data && data.properties && data.properties.timeseries) {
        data.properties.timeseries.forEach(function(entry) {
            var slotMs = new Date(entry.time).getTime();
            if (slotMs < now - 3600000 || slotMs > cutoff) return;
            var d = new Date(slotMs);
            d.setMinutes(0, 0, 0);
            var key    = d.toISOString();
            var inst   = entry.data.instant.details;
            var next1h = entry.data.next_1_hours;
            // wind_speed from MET Norway is in m/s — convert to km/h
            // ultraviolet_index_clear_sky only present in complete API
            var uv = (inst.ultraviolet_index_clear_sky !== undefined) ? inst.ultraviolet_index_clear_sky : null;
            slots[key] = {
                temp_c:       inst.air_temperature,
                wind_kph:     (inst.wind_speed || 0) * 3.6,
                wind_dir_deg: inst.wind_from_direction || 0,
                precip_mm:    next1h ? (next1h.details.precipitation_amount || 0) : null,
                rain_prob:    null,
                cloud_pct:    (inst.cloud_area_fraction !== undefined) ? inst.cloud_area_fraction : null,
                uv_index:     uv
            };
        });
    }
    msg.payload = { source: 'met_norway', slots: slots };
} catch(e) {
    node.warn('MET Norway parse error: ' + e.message);
    msg.payload = { source: 'met_norway', slots: {} };
}
