try {
    var text = msg.payload;
    var rainCurve = [];

    if (typeof text === 'string' && text.trim().length > 0) {
        var baseTime = new Date();
        baseTime.setSeconds(0, 0);

        text.trim().split('\n').forEach(function(line, i) {
            var parts = line.trim().split('|');
            var value = parseInt(parts[0], 10);
            if (isNaN(value)) return;
            // Convert Buienradar 0-255 intensity to mm/h: 10^((value-109)/32)
            var mmh = (value <= 0) ? 0 : Math.pow(10, (value - 109) / 32);
            var slotTime = new Date(baseTime.getTime() + i * 5 * 60000);
            rainCurve.push({
                time:            slotTime.toISOString(),
                time_offset_min: i * 5,
                mmh:             Math.round(mmh * 100) / 100
            });
        });
    }
    msg.payload = { source: 'buienradar_rain', rain_curve_5min: rainCurve, slots: {} };
} catch(e) {
    node.warn('Buienradar rain parse error: ' + e.message);
    msg.payload = { source: 'buienradar_rain', rain_curve_5min: [], slots: {} };
}
msg.topic = 'weather_agg';
return msg;

let discovery_topic = "homeassistant";
let root_topic = "weather";

let pobject = [
    // { type: "sensor", name: "Some name",              varname: "test_variable",        unique_id: "",             unit: "variable" },
    { type: "sensor", name: "Weather Forecast HE", varname: "weather_forecast_he", unique_id: "", unit: "variable" },
];

msg.pobject = pobject;
msg.discovery_topic = discovery_topic;
msg.root_topic = root_topic;

return msg;

var sources = msg.payload;

// Separate rain curve from forecast sources
var rainCurve       = [];
var forecastSources = [];

sources.forEach(function(s) {
    if (!s || !s.source) return;
    if (s.source === 'buienradar_rain') {
        rainCurve = s.rain_curve_5min || [];
    } else {
        forecastSources.push(s);
    }
});

// Collect all unique time keys from forecast sources
var allKeys = {};
forecastSources.forEach(function(s) {
    Object.keys(s.slots || {}).forEach(function(k) { allKeys[k] = true; });
});
var sortedKeys = Object.keys(allKeys).sort();

// Circular mean for wind direction
function circularMean(angles) {
    var valid = angles.filter(function(a) { return a !== null && a !== undefined && !isNaN(a); });
    if (!valid.length) return null;
    var sinSum = 0, cosSum = 0;
    valid.forEach(function(a) {
        sinSum += Math.sin(a * Math.PI / 180);
        cosSum += Math.cos(a * Math.PI / 180);
    });
    var mean = Math.atan2(sinSum / valid.length, cosSum / valid.length) * 180 / Math.PI;
    return Math.round((mean + 360) % 360);
}

// Median ignoring nulls
function median(arr) {
    var valid = arr.filter(function(v) { return v !== null && v !== undefined && !isNaN(v); });
    if (!valid.length) return null;
    var sorted = valid.slice().sort(function(a, b) { return a - b; });
    var mid = Math.floor(sorted.length / 2);
    return sorted.length % 2 === 0 ? (sorted[mid - 1] + sorted[mid]) / 2 : sorted[mid];
}

// 16-point compass label
function windLabel(deg) {
    if (deg === null || deg === undefined) return null;
    var dirs = ['N','NNE','NE','ENE','E','ESE','SE','SSE','S','SSW','SW','WSW','W','WNW','NW','NNW'];
    return dirs[Math.round(deg / 22.5) % 16];
}

// ── Solar power model ──────────────────────────────────────────────────────
var LAT    = 52.5185;  // Lelystad latitude, °N
var LON    = 5.4752;   // Lelystad longitude, °E
var TILT   = 22;       // Panel tilt from horizontal, degrees (all arrays)
var PR     = 0.82;     // System performance ratio (inverter, cables, temp, soiling)
var ALBEDO = 0.2;      // Ground reflectance

// Three arrays, all at TILT=22°. Azimuth from South, positive=West.
var ARRAYS = [
    { kwp: 3690, az:  -60 },  // East-facing
    { kwp: 7790, az:   30 },  // South-facing (SSW)
    { kwp: 3690, az:  120 }   // West-facing
];

// Returns estimated AC power output in watts for one hourly slot (sum of all arrays).
// Uses direct+diffuse split when available (Open-Meteo/Weerlive gr),
// otherwise falls back to Erbs decomposition of GHI alone.
function solarPowerW(isoTime, ghi, directH, diffuseH) {
    if (!ghi || ghi <= 0) return 0;

    // Use slot midpoint for sun-position accuracy
    var d   = new Date(new Date(isoTime).getTime() + 30 * 60000);
    var soy = new Date(Date.UTC(d.getUTCFullYear(), 0, 0));
    var doy = Math.ceil((d - soy) / 86400000);

    // Solar geometry
    var B    = 2 * Math.PI / 365 * (doy - 81);
    var decl = 23.45 * Math.sin(B) * Math.PI / 180;                       // declination, rad
    var eot  = 9.87*Math.sin(2*B) - 7.53*Math.cos(B) - 1.5*Math.sin(B);  // equation of time, min
    var utcMin = d.getUTCHours() * 60 + d.getUTCMinutes();
    var omega  = ((utcMin + (LON/15)*60 + eot) / 60 - 12) * 15 * Math.PI / 180; // hour angle, rad

    var lat  = LAT  * Math.PI / 180;
    var tilt = TILT * Math.PI / 180;

    // Solar elevation — return 0 if sun is below ~2° horizon
    var sinElev = Math.sin(lat)*Math.sin(decl) + Math.cos(lat)*Math.cos(decl)*Math.cos(omega);
    if (sinElev <= Math.sin(2 * Math.PI / 180)) return 0;

    // Beam/diffuse split — shared for all arrays
    var Gb, Gd;
    if (directH !== null && directH !== undefined &&
        diffuseH !== null && diffuseH !== undefined) {
        Gb = directH;
        Gd = diffuseH;
    } else {
        // Erbs (1982) decomposition from GHI alone
        var I0  = 1361 * (1 + 0.033 * Math.cos(2 * Math.PI * doy / 365));
        var kt  = Math.min(ghi / Math.max(I0 * sinElev, 1), 1);  // clearness index
        var kd  = kt <= 0.22 ? 1 - 0.09 * kt
                : kt <= 0.80 ? 0.9511 - 0.1604*kt + 4.388*kt*kt - 16.638*kt*kt*kt + 12.336*kt*kt*kt*kt
                : 0.165;
        Gd = kd * ghi;
        Gb = Math.max(0, ghi - Gd);
    }

    // Sky-diffuse and ground-reflected components depend only on tilt (same for all arrays)
    var diffuseComponent = Gd * (1 + Math.cos(tilt)) / 2;
    var groundComponent  = ghi * ALBEDO * (1 - Math.cos(tilt)) / 2;

    // Sum AC power contribution from each array
    var totalW = 0;
    ARRAYS.forEach(function(arr) {
        var azP = arr.az * Math.PI / 180;   // azimuth from South, positive=West

        // Angle of incidence on this tilted surface (Duffie & Beckman, eq 1.6.2)
        var cosAOI =
            Math.sin(decl)*Math.sin(lat)*Math.cos(tilt)
          - Math.sin(decl)*Math.cos(lat)*Math.sin(tilt)*Math.cos(azP)
          + Math.cos(decl)*Math.cos(lat)*Math.cos(tilt)*Math.cos(omega)
          + Math.cos(decl)*Math.sin(lat)*Math.sin(tilt)*Math.cos(azP)*Math.cos(omega)
          + Math.cos(decl)*Math.sin(tilt)*Math.sin(azP)*Math.sin(omega);
        cosAOI = Math.max(0, cosAOI);  // negative = sun behind panel

        var poa =
            Math.max(0, Gb * cosAOI / sinElev) +  // beam component
            diffuseComponent +                     // isotropic sky diffuse
            groundComponent;                       // ground reflected

        totalW += arr.kwp * (poa / 1000) * PR;
    });

    return Math.round(Math.max(0, totalW));
}
// ──────────────────────────────────────────────────────────────────────────

var now = Date.now();

var forecastSlots = sortedKeys.map(function(key) {
    var slotTime = new Date(key).getTime();
    var temps = [], windSpeeds = [], windDirs = [], precips = [], rainProbs = [], clouds = [];
    var solarRads = [], directRads = [], diffuseRads = [], uvIndices = [];
    var forecastCount = 0;

    forecastSources.forEach(function(s) {
        var slot = (s.slots || {})[key];
        if (!slot) return;
        forecastCount++;
        if (slot.temp_c                !== null && slot.temp_c                !== undefined) temps.push(slot.temp_c);
        if (slot.wind_kph              !== null && slot.wind_kph              !== undefined) windSpeeds.push(slot.wind_kph);
        if (slot.wind_dir_deg          !== null && slot.wind_dir_deg          !== undefined) windDirs.push(slot.wind_dir_deg);
        if (slot.precip_mm             !== null && slot.precip_mm             !== undefined) precips.push(slot.precip_mm);
        if (slot.rain_prob             !== null && slot.rain_prob             !== undefined) rainProbs.push(slot.rain_prob);
        if (slot.cloud_pct             !== null && slot.cloud_pct             !== undefined) clouds.push(slot.cloud_pct);
        if (slot.solar_radiation_wm2   !== null && slot.solar_radiation_wm2   !== undefined) solarRads.push(slot.solar_radiation_wm2);
        if (slot.direct_radiation_wm2  !== null && slot.direct_radiation_wm2  !== undefined) directRads.push(slot.direct_radiation_wm2);
        if (slot.diffuse_radiation_wm2 !== null && slot.diffuse_radiation_wm2 !== undefined) diffuseRads.push(slot.diffuse_radiation_wm2);
        if (slot.uv_index              !== null && slot.uv_index              !== undefined) uvIndices.push(slot.uv_index);
    });

    if (!forecastCount) return null;

    // Majority vote on rain: >0.3 mm/h = raining
    var rainyVotes   = precips.filter(function(p) { return p > 0.3; }).length;
    var rainMajority = precips.length > 0 ? rainyVotes / precips.length : 0;

    // Confidence: weighted combination of model coverage and temperature agreement
    var coverageScore = forecastCount / forecastSources.length;
    var tempAgreement = 1;
    if (temps.length > 1) {
        var mean     = temps.reduce(function(a, b) { return a + b; }, 0) / temps.length;
        var variance = temps.reduce(function(acc, t) { return acc + Math.pow(t - mean, 2); }, 0) / temps.length;
        var stdDev   = Math.sqrt(variance);
        // 0°C std = full confidence; 3°C std = half confidence
        tempAgreement = Math.max(0, 1 - stdDev / 3);
    }
    var confidence = coverageScore * 0.3 + tempAgreement * 0.7;

    // Attach 5-min rain curve to slots within the next 2 hours
    var slotRainCurve = null;
    if (slotTime >= now && slotTime < now + 2 * 3600000 && rainCurve.length > 0) {
        var curve = rainCurve.filter(function(r) {
            var rt = new Date(r.time).getTime();
            return rt >= slotTime && rt < slotTime + 3600000;
        });
        if (curve.length > 0) slotRainCurve = curve;
    }

    var temp     = median(temps);
    var windKph  = median(windSpeeds);
    var windDir  = circularMean(windDirs);
    var precipMm = median(precips);
    var rainProbFinal = rainProbs.length > 0 ? median(rainProbs) : rainMajority;
    var cloudPct = median(clouds);

    var solarWm2   = median(solarRads);
    var directWm2  = median(directRads);
    var diffuseWm2 = median(diffuseRads);
    var uvIdx      = median(uvIndices);

    var result = {
        time:                  key,
        temp_c:                temp     !== null ? Math.round(temp     * 10) / 10   : null,
        wind_kph:              windKph  !== null ? Math.round(windKph  * 10) / 10   : null,
        wind_dir_deg:          windDir,
        wind_dir_label:        windLabel(windDir),
        precip_mm:             precipMm !== null ? Math.round(precipMm * 100) / 100 : null,
        rain_prob:             Math.round(rainProbFinal * 100) / 100,
        rain_majority:         Math.round(rainMajority  * 100) / 100,
        cloud_pct:             cloudPct  !== null ? Math.round(cloudPct)             : null,
        solar_radiation_wm2:   solarWm2  !== null ? Math.round(solarWm2)             : null,
        direct_radiation_wm2:  directWm2 !== null ? Math.round(directWm2)            : null,
        diffuse_radiation_wm2: diffuseWm2!== null ? Math.round(diffuseWm2)           : null,
        uv_index:              uvIdx     !== null ? Math.round(uvIdx * 10) / 10      : null,
        confidence:            Math.round(confidence * 100) / 100,
        model_sources:         forecastCount
    };

    if (slotRainCurve) result.rain_curve_5min = slotRainCurve;
    result.solar_power_w = solarPowerW(key, solarWm2, directWm2, diffuseWm2);
    return result;
}).filter(function(s) { return s !== null; });

msg.payload = JSON.stringify({
    location:     { name: 'Lelystad', lat: 52.5185, lon: 5.4752 },
    generated_at: new Date().toISOString(),
    sources: {
        forecast:   forecastSources.map(function(s) { return s.source; }),
        rain_radar: rainCurve.length > 0 ? ['buienradar_rain'] : []
    },
    slot_count:   forecastSlots.length,
    forecast:     forecastSlots
});
msg.topic = 'weather/lelystad/forecast';
return msg;

try {
    var data  = msg.payload;
    var slots = {};
    var now    = Date.now();
    var cutoff = now + 48 * 3600 * 1000;

    var days = data && data.days;
    if (!days || !days.length) {
        msg.payload = { source: 'buienradar_forecast', slots: {} };
        msg.topic = 'weather_agg';
        return msg;
    }

    days.forEach(function(day) {
        var dayUv = (typeof day.uvindex === 'number') ? day.uvindex : null;
        (day.hours || []).forEach(function(h) {
            // datetimeutc has no Z — append it to parse as UTC
            var isoKey = h.datetimeutc + 'Z';
            var slotMs = new Date(isoKey).getTime();
            if (isNaN(slotMs) || slotMs < now - 3600000 || slotMs > cutoff) return;

            var d = new Date(slotMs);
            d.setMinutes(0, 0, 0);
            var key = d.toISOString();

            var windKph = (typeof h.windspeedms === 'number') ? Math.round(h.windspeedms * 3.6 * 10) / 10 : null;
            var solar = (typeof h.sunpower === 'number' && h.sunpower >= 0) ? Math.round(h.sunpower) : null;

            slots[key] = {
                temp_c:                (typeof h.temperature          === 'number') ? h.temperature          : null,
                wind_kph:              windKph,
                wind_dir_deg:          (typeof h.winddirectiondegrees === 'number') ? h.winddirectiondegrees : null,
                precip_mm:             (typeof h.precipitationmm      === 'number') ? h.precipitationmm      : null,
                rain_prob:             null,
                cloud_pct:             (typeof h.cloudcover           === 'number') ? h.cloudcover           : null,
                solar_radiation_wm2:   solar,
                direct_radiation_wm2:  null,
                diffuse_radiation_wm2: null,
                uv_index:              dayUv
            };
        });
    });

    msg.payload = { source: 'buienradar_forecast', slots: slots };
} catch(e) {
    node.warn('Buienradar forecast parse error: ' + e.message);
    msg.payload = { source: 'buienradar_forecast', slots: {} };
}
msg.topic = 'weather_agg';
return msg;

try {
    var data  = msg.payload;
    var slots = {};
    var now    = Date.now();
    var cutoff = now + 48 * 3600 * 1000;

    if (data && data.forecast && data.forecast.forecastday) {
        data.forecast.forecastday.forEach(function(day) {
            (day.hour || []).forEach(function(h) {
                // h.time_epoch is Unix seconds, UTC
                var slotMs = h.time_epoch * 1000;
                if (slotMs < now - 3600000 || slotMs > cutoff) return;
                var d = new Date(slotMs);
                d.setMinutes(0, 0, 0);
                var key = d.toISOString();
                slots[key] = {
                    temp_c:                (typeof h.temp_c         === 'number') ? h.temp_c         : null,
                    wind_kph:              (typeof h.wind_kph       === 'number') ? h.wind_kph       : null,
                    wind_dir_deg:          (typeof h.wind_degree    === 'number') ? h.wind_degree    : null,
                    precip_mm:             (typeof h.precip_mm      === 'number') ? h.precip_mm      : null,
                    rain_prob:             (typeof h.chance_of_rain === 'number') ? h.chance_of_rain : null,
                    cloud_pct:             (typeof h.cloud          === 'number') ? h.cloud          : null,
                    solar_radiation_wm2:   null,
                    direct_radiation_wm2:  null,
                    diffuse_radiation_wm2: null,
                    uv_index:              (typeof h.uv             === 'number') ? h.uv             : null
                };
            });
        });
    }
    msg.payload = { source: 'weatherapi', slots: slots };
} catch(e) {
    node.warn('WeatherAPI parse error: ' + e.message);
    msg.payload = { source: 'weatherapi', slots: {} };
}
